import multiprocessing

def shared_counter(counter):
    for _ in range(counter):
        counter.value += 1
    return counter.value

if __name__ == '__main__':
    manager = multiprocessing.Manager()
    counter = manager.Value('i', 0)
    processes = [multiprocessing.Process(target=shared_counter, args=(counter,)) for _ in range(4)]
    for p in processes:
        p.start()
    for p in processes:
        p.join()
    print('done', counter.value)

