import multiprocessing

def row_sum(row):
    return sum(row)

if __name__ == '__main__':
    matrix = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ]
    with multiprocessing.Pool(processes=3) as pool:
        results = pool.map(row_sum, matrix)
    print('Row sums:', results)
